class Account:
    """Ett bankkonto med nummer, ägare och saldo"""

    def __init__(self, number, owner, balance=0):
        self.__number = number
        self.__owner = owner
        self.__balance = balance

    def get_balance(self):
        """Returnerar saldot"""
        return self.__balance

    def __str__(self):
        return f"{self.__number}: {self.__owner}, {self.__balance} kr"

    def deposit(self, amount):
        """Sätter in amount kronor på kontot"""
        if amount <= 0:
            raise ValueError("beloppet måste vara positivt")
        self.__balance += amount

    def withdraw(self, amount):
        """Tar ut amount kronor, om de finns på kontot"""
        if amount <= 0:
            raise ValueError("beloppet måste vara positivt")
        if amount > self.__balance:
            raise ValueError(f"{self.__number} har inte {amount} kr")
        self.__balance -= amount

class Amount:
    """Ett belopp i kronor och ören"""

    def __init__(self, kronor, ore=0):
        if kronor < 0 or ore < 0:
            raise ValueError("ett belopp kan inte vara negativt")
        self.__ore = 100 * kronor + ore

    def __add__(self, other):
        if isinstance(other, int):
            other = Amount(other)
        return Amount(0, self.__ore + other.__ore)

    def __str__(self):
        return f"{self.__ore // 100},{self.__ore % 100:02} kr"


def main():
    print(Amount(500) + Amount(12, 50))
    print(sum([Amount(500), Amount(12, 50)]))


if __name__ == "__main__":
    main()

class SavingsAccount(Account):
    """Ett sparkonto: ett konto som också ger ränta"""

    def __init__(self, number, owner, balance=0, rate=0.02):
        super().__init__(number, owner, balance)
        self.__rate = rate

    def add_interest(self):
        """Sätter in räntan, i hela kronor, på saldot"""
        interest = round(self.get_balance() * self.__rate)
        if interest > 0:
            self.deposit(interest)

