def save(accounts, filename):
    """Sparar kontona i filen filename, ett konto per rad"""
    with open(filename, "w") as file:
        for number, balance in accounts.items():
            file.write(f"{number},{balance}\n")


def load(filename):
    """Läser kontona ur filen filename"""
    accounts = {}
    try:
        with open(filename) as file:
            for line in file:
                number, balance = line.strip().split(",")
                accounts[number] = int(balance)
    except FileNotFoundError:
        print(f"Hittar inte {filename}.")
    return accounts


def main():
    save({"1001": 1500, "1002": 300}, "konton.txt")
    save({"1003": 2000}, "konton.txt")
    print(load("konton.txt"))


if __name__ == "__main__":
    main()

